import java.io.IOException;
import java.nio.file.*;
import java.util.List;

public class Main {
    static String summarise(Path path) {
        return path.toString();
    }

    public static void main(String[] args) throws IOException {
        Files.write(Path.of("scores.txt"), List.of("70", "85", "ninety", "91", "75"));
        System.out.println(summarise(Path.of("scores.txt")));
        System.out.println(summarise(Path.of("missing.txt")));
    }
}
